import{eco4Tasks}from './eco4-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const T=(x,y,s,n=17,c='#faf5ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;const L=(a,b,c='#c1d3ce',w=3)=>`<path d="M${a[0]} ${a[1]}L${b[0]} ${b[1]}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const C=(x,y,r=7,c='#efad92')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;const B=(x,y,w,h,c='#365362')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="#a7c4bf"/>`;export const eco4SVG=(a,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${esc(label)}">${a}</svg>`;
const tree=(x,y)=>`<path d="M${x} ${y}v65" stroke="#b5a188" stroke-width="8"/><path d="M${x} ${y-45}l-27 55h54z" fill="#92b2a0"/>`;
export function impactFigure({kind='biodiversity',state='0',concealed=false,step=0,progress=0,movie=false}={}){let base=kind.replace(/-(data|route)$/,''),data=kind.endsWith('-data'),routeView=kind.endsWith('-route'),a='',note='',phase=Math.min(3,Math.floor(progress*4));if(kind==='land-peat-cost')return eco4SVG(T(280,35,'One cost is not the whole decision',22)+B(45,100,210,180)+B(305,100,210,180)+T(150,145,'Peat compost',20)+T(410,145,'Supplied alternative',19)+T(150,205,'£4 / bag',28)+T(410,205,'£6 / bag',28)+T(280,335,'Compare cost, suitability, habitat and stored carbon',16)+T(280,420,'Original fictional prices · not current shopping advice',13),'Original fictional comparison: peat compost £4 per bag, alternative £6; £2 difference. Evaluate growing needs, affordability, habitat and carbon impacts.');if(kind==='warming-evidence')return eco4SVG(T(280,35,'Strong wider evidence; bounded local predictions',20)+[80,180,280].map((y,i)=>B(60,y,440,70)+T(280,y+42,['Peer-reviewed studies','Systematic reviews across evidence','Assess consensus and remaining uncertainty'][i],17)).join('')+L([280,150],[280,180])+L([280,250],[280,280])+T(280,410,'A local forecast can be uncertain without negating warming',14),'Evidence chain: peer-reviewed research, systematic review, scientific consensus. Incomplete complex local ecological predictions retain uncertainty.');if(concealed)return eco4SVG(T(280,220,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');
if(routeView)state='1';
if(base==='biodiversity'){
if(data||state==='0'){a=T(280,30,'Same abundance. Different species variety.',21);for(let side=0;side<2;side++){a+=B(35+side*275,85,215,245)+T(142+side*275,119,side?'Sample B':'Sample A',19);for(let i=0;i<16;i++){let x=78+side*275+i%4*43,y=157+Math.floor(i/4)*39,sp=side?0:i%4;a+=sp===0?C(x,y,10,'#c3cda9'):sp===1?`<rect x="${x-9}" y="${y-9}" width="18" height="18" fill="#ecb69d"/>`:sp===2?`<path d="M${x} ${y-12}l12 22h-24z" fill="#aacbd1"/>`:`<path d="M${x} ${y-12}l12 12 -12 12 -12 -12z" fill="#d8bed6"/>`;}a+=T(142+side*275,312,(side?'1 species':'4 species')+' ·16 individuals',15);}note='Equal-area original samples · symbols identify species';}
else{let lost=state==='1'||step>0;a=T(280,30,'Trace a remaining food route',23);for(let[x,y,label]of[[100,130,'Seeds'],[100,290,'Insects'],[440,210,'Bird']]){a+=B(x-65,y-35,130,70,label==='Seeds'&&lost?'#61565b':'#365362')+T(x,y+6,label,20);}a+=L([165,130],[375,210],lost?'#ffffff22':'#efb49b')+L([165,290],[375,210],'#b4d2c6')+T(280,355,lost?'Seeds lost; insect route remains':'Two displayed food routes',18);note='Links do not measure food quantity or guarantee survival';}}
if(base==='waste'){
a=T(280,30,data?'Evaluate the treatment indicator':'Trace a pollution pathway',23);if(data){a+=L([100,330],[490,330]);for(let[i,v]of[60,15].entries())a+=B(145+i*200,330-v*3,75,v*3,i?'#99bbb0':'#e8ab94')+T(182+i*200,355,i?'After':'Before',17)+T(182+i*200,320-v*3,v+' units',17);a+=T(280,390,'45 / 60 removed ·75% of the initial indicator',17);note='One original indicator · not proof of complete recovery';}else{let rows=state==='2'?['Smoke / acidic gases','Air transport and exposure','Possible harm to organisms']:state==='0'?['Population × consumption','Resource demand and waste','Handling affects pollution risk']:['Sewage / nutrient runoff','Growth → dead organic material','Decay can lower dissolved oxygen'];for(let[i,s]of rows.entries()){a+=B(60,80+i*92,440,66)+T(280,120+i*92,s,18);if(i<2)a+=L([280,146+i*92],[280,168+i*92]);}if(movie){let y=105+progress*205;a+=C(40,y,8);}note='Selected causal route · not identical effects for every pollutant';}}
if(base==='land-peat'){
a=T(280,30,data?'Keep the habitat area account':'Peat stores habitat and carbon',23);if(data||state==='0'&&!movie){for(let i=0;i<10;i++)a+=B(50+i%5*94,100+Math.floor(i/5)*100,80,80,i<3?'#a98e80':'#759a87')+T(90+i%5*94,145+Math.floor(i/5)*100,i<3?'Built':'Habitat',14);a+=T(280,345,'100 ha −30 ha converted =70 ha habitat',19);note='Original land account · area alone is not species variety';}else{a+=B(50,85,460,250,'#435f60');for(let i=0;i<5;i++)a+=`<rect x="55" y="${165+i*31}" width="450" height="28" fill="${['#8d795f','#7e674f','#69533f','#584637','#4b3d33'][i]}"/>`;a+=T(280,125,'Waterlogged peat: slow accumulation',18)+T(280,210,'Stored organic carbon',20);if(movie&&phase>0||!movie&&state==='2'){a+=`<path d="M360 160V335H505V160" fill="#1a344b"/>`+T(432,225,'Exposed',16)+T(432,250,'peat',16)+C(430,150-progress*80,9)+T(430,70,'CO₂ to air',17);}a+=T(280,375,'Extraction loses habitat; decay/burning releases CO₂',16);note='Symbolic layers · no measured carbon budget or formation time';}}
if(base==='deforestation'){
a=T(280,30,data?'Compare competing land uses':'Forest clearance changes several pathways',21);for(let i=0;i<10;i++){let x=65+i%5*100,y=150+Math.floor(i/5)*120,cleared=data?i>=6:movie?i>=10-Math.floor(progress*4):state==='1'?i>=6:false;a+=B(x-34,y-57,78,95,cleared?'#88765f':'#3f6259');if(!cleared)a+=tree(x+5,y-7);else a+=T(x+5,y-6,i<8?'Cattle':i===8?'Rice':'Biofuel',13);}a+=T(280,370,data?'60 ha retained ·20 cattle ·10 rice ·10 biofuel':'Habitat removed · CO₂ release · less later uptake',17);note='Original100 ha plan · land percentage is not species mortality';}
if(base==='warming'){
a=T(280,30,data||state==='2'&&!movie?'Read the long-term model trend':'Changing energy balance affects habitats',22);if(data||state==='2'&&!movie){let vals=[0,.2,.1,.5];a+=L([85,80],[85,330])+L([85,330],[505,330]);for(let i=0;i<4;i++){let x=110+i*120,y=330-vals[i]*400;a+=C(x,y,7)+T(x,y-15,vals[i].toFixed(1),16)+T(x,355,'D'+i,15);if(i)a+=L([x-120,330-vals[i-1]*400],[x,y],'#edb49b');}a+=T(35,80,'0.6',14)+T(45,334,'0.0',14)+T(280,390,'Model decades · anomaly / °C',18);note='Original fictional data · defined baseline · not current observations';}else{a+=`<ellipse cx="280" cy="300" rx="220" ry="40" fill="#74998e"/><path d="M60 220Q280 50 500 220" fill="none" stroke="#b6cbd1" stroke-width="24" opacity=".4"/>`+L([105,75],[200,280],'#e7ca91',6)+L([290,285],[370,95],'#efad92',6)+L([350,140],[400,280],'#efad92',4)+T(112,65,'Sunlight',16)+T(390,70,'Infrared',16)+T(280,350,'Some infrared absorbed and re-emitted',16);if(movie)a+=C(290+80*progress,285-190*progress,7);a+=T(280,386,'Distribution · breeding · migration · extinction risk',15);note='Qualitative routes · not a lid, energy creation or flux calibration';}}
let route=eco4Tasks[base]?.find(t=>t.type==='sequence');if(step&&route)a+=T(280,62,route.labels[Math.min(step-1,route.labels.length-1)],14,'#ffd0b2');a+=T(280,426,note,12);return eco4SVG(a,`${base}. ${data?'Original supplied numerical evidence. ':''}${note}. ${state==='1'&&base==='biodiversity'?'Seeds removed; bird retains insect food route; no guaranteed survival. ':''}${step&&route?'Completed stages: '+route.labels.slice(0,step).join('; '):''}`);}
